    private void forgetRule(String description, String name) {
        List<StoreEntry> entries = entries();
        StoreEntry own = null;
        for (StoreEntry entry : entries) {
            if (entry.description.equals(description)) {
                own = entry;
                break;
            }
        }
        if (own == null) {
            return;
        }
        PathInfo pathInfo = inspectPath(name);
        boolean shared = isShared(own, entries);
        FileSnapshot previous = null;
        if (!shared && pathInfo.realPath != null && Files.exists(pathInfo.realPath)) {
            if (pathInfo.reachesIndex) {
                throw new StoreUpdateFailedException("The rule file leads to the rule index");
            }
            previous = FileSnapshot.capture(pathInfo.realPath);
            try {
                Files.delete(pathInfo.realPath);
            } catch (IOException e) {
                throw new StoreUpdateFailedException(e);
            }
        }
        try {
            storedRules.removeAndSync(description);
        } catch (RuntimeException e) {
            if (previous != null) {
                previous.restore();
            }
            throw e;
