    @Override
    public List<String> getViolations(ArchRule rule) {
        synchronized (storeLock) {
            String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
            List<String> result = readLines(ruleDetailsFileName);
            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
            return result;
        }
    }

    private List<String> readLines(String fileName) {
        String violationsText = readStoreFile(fileName);
        if (LINE_BREAKS_ONLY.matcher(violationsText).matches()) {
            return Collections.emptyList();
        }
        List<String> result = new ArrayList<>();
        StringBuilder current = new StringBuilder();
        for (int i = 0; i < violationsText.length(); i++) {
            char character = violationsText.charAt(i);
            if (character == '\n') {
                int slashes = 0;
                for (int j = current.length() - 1; j >= 0 && current.charAt(j) == '\\'; j--) {
                    slashes++;
                }
                if (slashes % 2 == 1) {
                    current.deleteCharAt(current.length() - 1);
                    current.append('\n');
                } else {
                    if (current.length() > 0) {
                        result.add(unescape(current.toString()));
                    }
                    current.setLength(0);
                }
            } else {
                current.append(character);
            }
        }
        if (current.length() > 0) {
            result.add(unescape(current.toString()));
        }
        return result;
    }

    private String readStoreFile(String fileName) {
        PathInfo pathInfo = inspectPath(fileName);
        try {
            return new String(toByteArray(pathInfo.path.toFile()), UTF_8);
        } catch (IOException | RuntimeException e) {
            throw new StoreReadException(e);
        }
    }

    private String escape(String violation) {
        return violation.replace("\n", "\\\n");
    }

    private String unescape(String violation) {
        return violation.replace("\\\n", "\n");
    }

    private IntegrityReport inspectIntegrity() {
        List<StoreEntry> entries = entries();
        Map<String, Integer> derivedNameCounts = new HashMap<>();
        for (StoreEntry entry : entries) {
            // A random name has no derivation that can be recomputed for an existing entry. Its
            // recorded name is therefore the only derived name meaningful to integrity checking.
            entry.derivedName = randomFileNames ? entry.name : createRuleFileNameForInspection(entry.description);
            derivedNameCounts.put(entry.derivedName, derivedNameCounts.getOrDefault(entry.derivedName, 0) + 1);
            entry.pathInfo = inspectPath(entry.name);
            entry.broken = entry.pathInfo.broken();
            if (!entry.broken) {
                entry.resolved = isResolved(entry.pathInfo.path);
            }
            entry.misplaced = !randomFileNames && !entry.name.equals(entry.derivedName);
        }

        for (StoreEntry entry : entries) {
            entry.colliding = derivedNameCounts.get(entry.derivedName) > 1;
            entry.occupied = entry.misplaced && isOccupied(entry, entries);
            entry.shared = isShared(entry, entries);
        }

        List<String> unownedFiles = findUnownedFiles(entries);
        return new IntegrityReport(entries, unownedFiles);
    }

    private String createRuleFileNameForInspection(String description) {
        String result;
        try {
            result = ruleViolationFileNameStrategy.createRuleFileName(description);
        } catch (RuntimeException e) {
            throw new StoreInitializationFailedException(e);
        }
        if (result == null || result.isEmpty()) {
            throw new StoreInitializationFailedException(String.format(
                    "RuleViolationFileNameStrategy returned no file name for rule '%s'", description));
        }
        return result;
    }

    private boolean isResolved(Path path) {
        try {
            return LINE_BREAKS_ONLY.matcher(new String(Files.readAllBytes(path), UTF_8)).matches();
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private boolean isOccupied(StoreEntry entry, List<StoreEntry> entries) {
        PathInfo derived = inspectPath(entry.derivedName);
        if (!derived.validPath || derived.escapesFolder || derived.reachesIndex || derived.existsWithoutFollowingLink) {
            return true;
        }
        for (StoreEntry other : entries) {
            if (other != entry && entry.derivedName.equals(other.name)) {
                return true;
            }
        }
        return false;
    }

    private boolean isShared(StoreEntry entry, List<StoreEntry> entries) {
        for (StoreEntry other : entries) {
            if (entry == other) {
                continue;
            }
            if (entry.name.equals(other.name)) {
                return true;
            }
            if (entry.pathInfo != null && other.pathInfo != null
                    && entry.pathInfo.path != null && other.pathInfo.path != null
                    && sameFile(entry.pathInfo.path, other.pathInfo.path)) {
                return true;
            }
        }
        return false;
    }

    private boolean sameFile(Path first, Path second) {
        try {
            return Files.exists(first) && Files.exists(second) && Files.isSameFile(first, second);
        } catch (IOException | SecurityException e) {
            return false;
        }
    }

    private List<String> findUnownedFiles(List<StoreEntry> entries) {
        List<String> result = new ArrayList<>();
        try (DirectoryStream<Path> files = Files.newDirectoryStream(storeFolder)) {
            for (Path file : files) {
                if (!Files.isRegularFile(file, java.nio.file.LinkOption.NOFOLLOW_LINKS)
                        || sameFile(file, storedRulesFile)) {
                    continue;
                }
                boolean owned = false;
                for (StoreEntry entry : entries) {
                    if (entry.pathInfo.path != null && sameFile(entry.pathInfo.path, file)) {
                        owned = true;
                        break;
                    }
                }
                if (!owned) {
                    result.add(file.getFileName().toString());
                }
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
        Collections.sort(result);
        return result;
    }

    private void repair(IntegrityReport report) {
        List<StoreEntry> changedEntries = new ArrayList<>();
        List<RepairOperation> operations = new ArrayList<>();
        try {
            for (StoreEntry entry : sortedEntries(report.entries)) {
                if (entry.shared) {
                    continue;
                }
                if (entry.broken || entry.resolved) {
                    if (entry.resolved && entry.pathInfo.realPath != null && Files.exists(entry.pathInfo.realPath)) {
                        operations.add(RepairOperation.delete(entry.pathInfo.realPath));
                    }
                    entry.remove = true;
                } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
                    PathInfo derived = inspectPath(entry.derivedName);
                    if (!derived.validStoreTarget() || derived.existsWithoutFollowingLink) {
                        continue;
                    }
                    operations.add(RepairOperation.move(entry.pathInfo.realPath, derived.path));
                    entry.name = entry.derivedName;
                    entry.pathInfo = derived;
                    entry.changed = true;
                }
                if (entry.remove || entry.changed) {
                    changedEntries.add(entry);
                }
            }

            for (RepairOperation operation : operations) {
                operation.apply();
            }
            if (!changedEntries.isEmpty()) {
                storedRules.applyEntryChanges(changedEntries);
            }
        } catch (IOException | RuntimeException e) {
            for (int i = operations.size() - 1; i >= 0; i--) {
                operations.get(i).undo();
            }
            if (e instanceof StoreInitializationFailedException) {
                throw (StoreInitializationFailedException) e;
            }
            throw new StoreInitializationFailedException("Cannot repair violation store integrity", e);
        }
    }

    private List<StoreEntry> entries() {
        List<StoreEntry> result = new ArrayList<>();
        for (Map.Entry<String, String> property : storedRules.entries().entrySet()) {
            result.add(new StoreEntry(property.getKey(), property.getValue()));
        }
        return result;
    }

    private List<StoreEntry> sortedEntries(List<StoreEntry> entries) {
        List<StoreEntry> result = new ArrayList<>(entries);
        result.sort(Comparator.comparing(entry -> entry.description));
        return result;
    }

    private PathInfo inspectPath(String name) {
        try {
            Path path = storeFolder.resolve(Paths.get(name));
            boolean existsWithoutFollowingLink = Files.exists(path, java.nio.file.LinkOption.NOFOLLOW_LINKS);
            Path realPath = null;
            try {
                realPath = path.toRealPath();
            } catch (IOException ignored) {
                // A missing or dangling path is described by the remaining fields.
            }
